// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Healthz El proceso está vivo
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
	// Readyz El proceso puede atender (hay conexión con Postgres)
	// (GET /readyz)
	Readyz(ctx context.Context, request ReadyzRequestObject) (ReadyzResponseObject, error)
	// AdminListCodes Listar o exportar códigos
	// (GET /v1/admin/codes)
	AdminListCodes(ctx context.Context, request AdminListCodesRequestObject) (AdminListCodesResponseObject, error)
	// AdminListCodeEvents Bitácora de un código
	// (GET /v1/admin/codes/{id}/events)
	AdminListCodeEvents(ctx context.Context, request AdminListCodeEventsRequestObject) (AdminListCodeEventsResponseObject, error)
	// AdminFulfillCode Marcar como entregado (REDEEMED → FULFILLED)
	// (POST /v1/admin/codes/{id}/fulfill)
	AdminFulfillCode(ctx context.Context, request AdminFulfillCodeRequestObject) (AdminFulfillCodeResponseObject, error)
	// AdminRevokeCode Revocar un código sin canjear (ISSUED → REVOKED)
	// (POST /v1/admin/codes/{id}/revoke)
	AdminRevokeCode(ctx context.Context, request AdminRevokeCodeRequestObject) (AdminRevokeCodeResponseObject, error)
	// AdminStats Totales por oferta de una campaña
	// (GET /v1/admin/stats)
	AdminStats(ctx context.Context, request AdminStatsRequestObject) (AdminStatsResponseObject, error)
	// ListHolderCodes Códigos de una persona (sin el código completo)
	// (GET /v1/codes)
	ListHolderCodes(ctx context.Context, request ListHolderCodesRequestObject) (ListHolderCodesResponseObject, error)
	// IssueCode Emitir un código para una persona y una oferta
	// (POST /v1/codes)
	IssueCode(ctx context.Context, request IssueCodeRequestObject) (IssueCodeResponseObject, error)
	// RedeemCode Canjear un código con el correo de la persona
	// (POST /v1/codes/redeem)
	RedeemCode(ctx context.Context, request RedeemCodeRequestObject) (RedeemCodeResponseObject, error)
	// ValidateCode Validar un código sin cambiar nada
	// (POST /v1/codes/validate)
	ValidateCode(ctx context.Context, request ValidateCodeRequestObject) (ValidateCodeResponseObject, error)
	// ListOffers Ofertas disponibles para la app emisora
	// (GET /v1/offers)
	ListOffers(ctx context.Context, request ListOffersRequestObject) (ListOffersResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Healthz operation middleware
func (sh *strictHandler) Healthz(w http.ResponseWriter, r *http.Request) {
	var request HealthzRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Healthz(ctx, request.(HealthzRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Healthz")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthzResponseObject); ok {
		if err := validResponse.VisitHealthzResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

